package mx.com.mesaregia.cotizaciones.application.service.impl; import mx.com.mesaregia.cotizaciones.api.request.ConfirmacionRequest; import mx.com.mesaregia.cotizaciones.api.response.ConfirmacionResponse; import mx.com.mesaregia.cotizaciones.application.service.CotizacionConfirmationOrchestrator; import mx.com.mesaregia.cotizaciones.domain.enums.*; import mx.com.mesaregia.cotizaciones.exception.*; import mx.com.mesaregia.cotizaciones.integration.client.*; import mx.com.mesaregia.cotizaciones.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*;
@Service public class CotizacionConfirmationOrchestratorImpl implements CotizacionConfirmationOrchestrator{private final CotizacionSupport s;private final CotizacionRepository cr;private final CotizacionDetalleRepository dr;private final EventoRepository er;private final PagoCoveragePort pagos;private final InventarioReservationPort reservas;private final OrdenCommandPort ordenes;public CotizacionConfirmationOrchestratorImpl(CotizacionSupport s,CotizacionRepository cr,CotizacionDetalleRepository dr,EventoRepository er,PagoCoveragePort p,InventarioReservationPort r,OrdenCommandPort o){this.s=s;this.cr=cr;this.dr=dr;this.er=er;pagos=p;reservas=r;ordenes=o;}
 @Transactional public ConfirmacionResponse confirmar(Long c,String key,String corr,ConfirmacionRequest r){if(key==null||key.isBlank())throw new BusinessRuleException("Idempotency-Key es obligatorio");if(corr==null||corr.isBlank())throw new BusinessRuleException("X-Correlation-Id es obligatorio");var q=s.get(c);if(!Objects.equals(q.getVersion(),r.version()))throw new ConflictException("Versión de concurrencia desactualizada");if(q.getIdVersionElegida()==null)throw new BusinessRuleException("Debe existir una versión elegida");var ver=s.version(c,q.getIdVersionElegida());if(ver.getEstadoVersion()!=EstadoVersion.ENVIADA)throw new BusinessRuleException("La versión elegida debe estar ENVIADA");var cob=pagos.consultar(c,ver.getId());if(!cob.cubierta())throw new BusinessRuleException("El importe requerido de confirmación aún no está cubierto");var ev=er.findByIdCotizacion(c).orElseThrow();var items=dr.findByIdCotizacionVersionOrderByOrdenAsc(ver.getId()).stream().filter(x->x.getTipoConcepto()==TipoConcepto.PRODUCTO).map(x->new InventarioReservationPort.Item(x.getIdConceptoExterno(),x.getCantidad())).toList();var res=reservas.reservar(key+":reserva",c,ver.getId(),ev.getFechaEvento(),ev.getHoraEvento(),items);try{var ord=ordenes.generar(key+":orden",c,ver.getId(),cob.referenciaPago(),res.referenciaReserva());var ant=q.getEstadoGeneral();q.setEstadoGeneral(EstadoCotizacion.CONFIRMADA);q.setReferenciaPagoExterna(cob.referenciaPago());q.setReferenciaReservaExterna(res.referenciaReserva());q.setFechaConfirmacion(LocalDateTime.now());q.setIdUsuarioModificacionExterno(r.idUsuario());q=cr.saveAndFlush(q);s.history(c,ver.getId(),"COTIZACION_CONFIRMADA",ant.name(),EstadoCotizacion.CONFIRMADA.name(),"Orden "+ord.folioOrden()+"; reserva "+res.referenciaReserva(),r.idUsuario());return new ConfirmacionResponse(c,ver.getId(),q.getEstadoGeneral(),cob.referenciaPago(),res.referenciaReserva(),ord.idOrden(),ord.folioOrden());}catch(RuntimeException ex){try{reservas.liberar(res.referenciaReserva());}catch(RuntimeException ignored){}throw ex;}}
}
